contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) {
        c = _c;
        deployer = msg.sender;
    }

    // We will: as the test contract (which is the owner because fresh C is deployed by the checker with this contract),
    // 1) set a caller address (cfo) to a chosen non-zero address 'caller',
    // 2) set a distributeAddress to a chosen non-zero address 'dst',
    // 3) ensure the contract has at least distributeAmount by transferring tokens to it from owner (this contract) using ERC20 transfer,
    // 4) call distributeToken() from the caller via try/catch, and observe revert flag,
    // The asserted property: if (a) caller is non-zero and (b) dst is non-zero and (c) c.balanceOf(address(c)) >= distributeAmount before distributeToken, then distributeToken called by caller MUST NOT revert and after the call balanceOf(address(c)) decreases by exactly distributeAmount and balanceOf(dst) increases by exactly distributeAmount.

    // Note: we interact only via c's public interface. We use the fact that this test contract deployed c so it is the owner and can call setCaller.

    function run(address caller, address dst) public payable {
        require(caller != address(0) && dst != address(0));

        // set the caller (cfo) to 'caller' as owner (this contract is owner)
        c.setCaller(caller);

        // set distributeAddress to dst by calling setDistributeAddress through onlyCaller; must be called by cfo
        // So we call setDistributeAddress from 'caller' using a low-level call: simulate caller by calling c via the caller address is not possible in this single-contract test.
        // Instead, we will transfer ownership of c to this contract's address is already owner, but setCaller expects onlyOwner to call setCaller and onlyCaller to call setDistributeAddress.
        // We set caller to an address we control: use address(this) as caller so we can call onlyCaller methods.
        // If input 'caller' is not address(this), then we can't invoke onlyCaller methods. To keep the rule general over inputs, require caller == address(this).
        require(caller == address(this));

        // Now set distributeAddress via onlyCaller (this contract)
        c.setDistributeAddress(dst);

        // We need to ensure contract c holds at least distributeAmount. We are the owner and initially received the initial supply at deployment of C; but test harness deploys C before this test contract's constructor? The problem statement guarantees c is fresh and was deployed by the checker, with this contract as deployer.
        // We attempt to transfer tokens from this contract (owner) to c to ensure sufficient balance.
        uint256 distributeAmount = c.distributeAmount();

        // Transfer tokens from this contract (which holds initial supply) to c. Use ERC20 transfer via public transfer on c since c is ERC20 token contract itself.
        // c.transfer is a public function that transfers from msg.sender. Call it to send tokens from this contract to c.
        c.transfer(address(c), distributeAmount);

        // Record balances before
        uint256 beforeC = c.balanceOf(address(c));
        uint256 beforeDst = c.balanceOf(dst);
        bool reverted;

        // Now call distributeToken from caller (this contract) which is set as cfo
        try c.distributeToken() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = c.balanceOf(address(c));
        uint256 afterDst = c.balanceOf(dst);

        // The asserted general rule:
        // If caller==address(this), dst != 0, and beforeC >= distributeAmount, then distributeToken must not revert and balances change by exactly distributeAmount.
        assert(!(caller == address(this) && dst != address(0) && beforeC >= distributeAmount) ||
               (reverted == false && beforeC - afterC == distributeAmount && afterDst - beforeDst == distributeAmount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We require the caller parameter to be this contract so we can call onlyCaller methods.
    // Parameters: dst - proposed distributeAddress; amountSent - tokens to transfer into c to ensure it has >= distributeAmount.
    function run(address dst, uint256 amountSent, address callerMustBe) public payable {
        require(callerMustBe == address(this));
        require(dst != address(0));

        // set this contract as the cfo so we can call onlyCaller functions
        c.setCaller(address(this));

        // set the distributeAddress to dst (onlyCaller)
        c.setDistributeAddress(dst);

        // ensure contract c has tokens: transfer amountSent from this contract (owner) to c
        // This contract is the owner (it deployed c as per harness). Use c.transfer to move tokens from this contract to c.
        // Only do transfer if amountSent > 0 to avoid wasting gas on zero transfer.
        if (amountSent > 0) {
            c.transfer(address(c), amountSent);
        }

        // Observe balances before
        uint256 beforeC = c.balanceOf(address(c));
        uint256 beforeDst = c.balanceOf(dst);

        // We do not have direct access to the private distributeAmount, but its value is a constant-like 2000*1e18 in the original contract; however we must not rely on reading private state.
        // Instead, we assert a relation that if beforeC is at least 2000*1e18 then distributeToken must succeed and transfer exactly 2000*1e18.
        // To keep the assertion general and not use private fields, we check behavior conditioned on beforeC >= 2000*1e18.

        bool reverted;
        try c.distributeToken() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = c.balanceOf(address(c));
        uint256 afterDst = c.balanceOf(dst);

        uint256 expected = 2000 * 1e18;

        // General rule asserted:
        // If this contract is the caller (we ensured it) and distributeAddress is set (dst != 0) and c had at least expected tokens,
        // then distributeToken must NOT revert and balances must change by exactly expected.
        assert(!(beforeC >= expected) || (reverted == false && beforeC - afterC == expected && afterDst - beforeDst == expected));
    }

    receive() external payable {}
}

